// NPC Constructor v6.0 (Declarativo OOP Standard + Carga Dinámica de Base)
(async function() {
  if (!game.defineStandardAgent) {
    try {
      var res = await fetch('/api/snippets/base-npc-skills');
      var snip = await res.json();
      if (snip && snip.code) (new Function(snip.code))();
    } catch(e) { console.error('Error cargando base-npc-skills:', e); }
  }

  await game.addMaterial('red_concrete');
  await game.addMaterial('sand');
  await game.addMaterial('yellow');

  game.defineStandardAgent({
    id: 'constructor',
    name: 'Constructor (Arena sobre Rojo)',
    block: 'yellow',
    buildBlock: 'sand',
    triggerFloor: 'red_concrete',
    margin: 1,
    passengers: true,
    tickMs: 200,
    skills: {
      caminataAzotea: true,
      lookAheadPrevent: true,
      construccionEnCapa: true,
      saltoTactico: false
    }
  });
})();
